/* =========================================================
   Stock y compras: catálogo, kardex, alertas, pedidos OT,
   compras (OC) y proveedores
   ========================================================= */
let INV={tab:'cat',q:'',cat:'all',sku:'all'};
function pendingDeliveries(){const r=[];S.ots.filter(o=>o.stage!=='ent').forEach(o=>o.items.forEach(i=>{if(i.sku&&i.ap===true&&i.rs!=='entregado')r.push({o,i})}));return r}

VIEWS.inventario={t:'Inventario y compras',ic:'box',render(){
  const low=lowParts(),pend=pendingDeliveries(),val=S.parts.reduce((a,p)=>a+p.stock*p.cost,0);
  const tabs=[['cat','Catálogo'],['ped','Pedidos de OT'+(pend.length?` (${pend.length})`:'')],['alert','Alertas de mínimos'+(low.length?` (${low.length})`:'')],['kdx','Kardex'],['oc','Compras'],['prov','Proveedores']];
  let body='';
  if(INV.tab==='cat'){const cats=[...new Set(S.parts.map(p=>p.cat))];
   const l=S.parts.filter(p=>(INV.cat==='all'||p.cat===INV.cat)&&(!INV.q||(p.name+p.sku+p.brand).toLowerCase().includes(INV.q)));
   body=`<div class="row mb"><input class="chip" placeholder="Buscar repuesto, SKU o marca…" value="${esc(INV.q)}" oninput="INV.q=this.value.toLowerCase();invRender()" style="min-width:280px"><select class="chip" onchange="INV.cat=this.value;refresh()"><option value="all">Todas las categorías</option>${cats.map(c=>`<option ${INV.cat===c?'selected':''}>${c}</option>`).join('')}</select><span class="sp"></span><button class="btn btn-o" onclick="exportStock()">${ic('download')} Excel</button><button class="btn btn-y" onclick="newPart()">${ic('plus')} Nuevo repuesto</button></div>
   <div class="card"><div class="tscroll"><table class="tbl"><thead><tr><th>SKU</th><th>Repuesto</th><th>Ubic.</th><th class="r">Costo</th><th class="r">Venta</th><th>Unidad</th><th>Stock</th><th>Estado</th><th></th></tr></thead><tbody id="invBody">${invRows(l)}</tbody></table></div></div>`}
  if(INV.tab==='ped')body=`<div class="card"><h3>Repuestos pedidos por OT <small>Almacén entrega al técnico y el stock se descuenta</small></h3>${pend.length?`<table class="tbl"><thead><tr><th>OT</th><th>Vehículo</th><th>Repuesto</th><th class="r">Cant.</th><th>Stock del repuesto</th><th>Estado</th><th></th></tr></thead><tbody>${pend.map(({o,i})=>{const p=part(i.sku);return `<tr><td class="click" onclick="openOT('${o.id}','rep')"><a style="color:var(--blue);font-weight:700;cursor:pointer">${o.id}</a></td><td>${plateTag(o.plate)}</td><td>${esc(i.desc)}<br><small>${i.sku}</small></td><td class="r">${i.qty} ${esc(p.unit)}</td><td>${stockCell(p,1)}</td><td>${rsPill(i)}</td><td class="r">${avail(p)>=i.qty||i.rs==='reservado'?`<button class="btn btn-b btn-s" onclick="deliverFromOT('${o.id}','${i.id}')">Entregar</button>`:`<button class="btn btn-o btn-s" onclick="quickPO('${i.sku}',${i.qty})">Pedir compra</button>`}</td></tr>`}).join('')}</tbody></table>`:'<div class="empty">No hay pedidos pendientes.</div>'}</div>`;
  if(INV.tab==='alert')body=`<div class="card"><h3>Repuestos bajo el mínimo <button class="btn btn-b btn-s" onclick="poFromLow()" ${low.length?'':'disabled'}>${ic('send')} Generar órdenes de compra</button></h3>${low.length?`<table class="tbl"><thead><tr><th>Repuesto</th><th>Proveedor</th><th>Stock</th><th class="r">Sugerido</th><th class="r">Costo est.</th></tr></thead><tbody>${low.map(p=>`<tr><td>${esc(p.name)}<br><small>${p.sku}</small></td><td>${esc(sup(p.sup).n)}<br><small>Entrega ${sup(p.sup).lead} día(s)</small></td><td>${stockCell(p)}</td><td class="r"><b>${suggestQty(p)}</b> ${esc(p.unit)}</td><td class="r">${money(suggestQty(p)*p.cost)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Todo el stock está sobre el mínimo.</div>'}</div>`;
  if(INV.tab==='kdx'){const l=S.kardex.filter(k=>INV.sku==='all'||k.sku===INV.sku).slice(0,60);
   body=`<div class="row mb"><select class="chip" onchange="INV.sku=this.value;refresh()"><option value="all">Todos los repuestos</option>${S.parts.map(p=>`<option value="${p.sku}" ${INV.sku===p.sku?'selected':''}>${esc(p.name)}</option>`).join('')}</select><span class="sp"></span><button class="btn btn-o" onclick="exportKardex()">${ic('download')} Excel</button></div>
   <div class="card"><p class="mut mb">Regla de oro: <b>nada sale sin una OT</b>. Todo movimiento queda con fecha, responsable y origen.</p><table class="tbl"><thead><tr><th>Fecha</th><th>Repuesto</th><th>Movimiento</th><th class="r">Cant.</th><th>Origen</th><th>Responsable</th></tr></thead><tbody>${l.map(k=>`<tr><td class="nw">${fmtDT(k.t)}</td><td>${esc(part(k.sku)?.name||k.sku)}</td><td>${pill(k.type,{entrada:'ok',salida:'info',reserva:'y',ajuste:'warn'}[k.type])}</td><td class="r"><b>${k.type==='salida'?'−':k.type==='entrada'?'+':''}${Math.abs(k.qty)}</b></td><td>${esc(k.ref)}</td><td>${esc(k.who)}</td></tr>`).join('')}</tbody></table></div>`}
  if(INV.tab==='oc')body=`<div class="row mb"><span class="sp"></span><button class="btn btn-y" onclick="newPO()">${ic('plus')} Nueva orden de compra</button></div><div class="card"><table class="tbl"><thead><tr><th>OC</th><th>Proveedor</th><th>Fecha</th><th>Entrega est.</th><th>Detalle</th><th class="r">Total</th><th>Estado</th><th></th></tr></thead><tbody>${S.pos.map(po=>`<tr><td><b>${po.id}</b></td><td>${esc(sup(po.sup).n)}</td><td>${fmtD(po.date)}</td><td>${fmtD(po.eta)}</td><td>${po.lines.map(l=>`${l.qty} × ${esc(part(l.sku)?.name||l.sku)}`).join('<br>')}</td><td class="r">${money(po.lines.reduce((a,l)=>a+l.qty*l.cost,0))}</td><td>${pill(po.st==='recibida'?'Recibida':'Enviada',po.st==='recibida'?'ok':'y')}</td><td class="r">${po.st!=='recibida'?`<button class="btn btn-b btn-s" onclick="receivePO('${po.id}')">Recibir mercadería</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;
  if(INV.tab==='prov')body=`<div class="grid g3">${S.suppliers.map(s=>{const ps=S.parts.filter(p=>p.sup===s.id);return `<div class="card"><h3>${esc(s.n)}</h3><p><small>RUC ${s.ruc} · ${s.tel}</small></p><p class="mt">${esc(s.cat)}</p><div class="row mt">${pill('Entrega '+s.lead+' d','info')}${pill('★ '+s.rate,'y')}${pill(ps.length+' productos','gray')}</div><div class="divider"></div><small>Último costo: ${ps.slice(0,2).map(p=>`${p.sku} ${money0(p.cost)}`).join(' · ')}</small></div>`}).join('')}</div>`;
  return `<div class="ph"><div><h2>Inventario <em>y compras</em></h2><p>Kardex, mínimos, reservas automáticas y compras. Se acabó el cuaderno.</p></div></div>
  <div class="grid g4 mb"><div class="kpi"><small>Stock valorizado</small><b>${money0(val)}</b><span>${S.parts.length} productos</span></div><div class="kpi ${low.length?'r':'g'}"><small>Bajo mínimo</small><b>${low.length}</b><span>${S.parts.filter(p=>p.stock<=0).length} sin stock</span></div><div class="kpi y"><small>Pedidos de OT</small><b>${pend.length}</b><span>Por entregar a técnicos</span></div><div class="kpi"><small>OC en camino</small><b>${S.pos.filter(p=>p.st!=='recibida').length}</b><span>Por recibir</span></div></div>
  <div class="tabs">${tabs.map(([k,n])=>`<button class="${INV.tab===k?'on':''}" onclick="INV.tab='${k}';refresh()">${n}</button>`).join('')}</div>${body}`}};
function invRows(l){return l.map(p=>`<tr><td><small><b>${p.sku}</b></small></td><td>${esc(p.name)}<br><small>${esc(p.brand)} · ${esc(p.cat)}</small></td><td>${p.loc}</td><td class="r">${money(p.cost)}</td><td class="r">${money(p.price)}</td><td>${esc(p.unit)}</td><td>${stockCell(p)}</td><td>${stockPill(p)}</td><td class="r"><button class="btn btn-o btn-s" onclick="adjustPart('${p.sku}')">Ajustar</button></td></tr>`).join('')||'<tr><td colspan="9" class="empty">Sin resultados</td></tr>'}
function invRender(){const l=S.parts.filter(p=>(INV.cat==='all'||p.cat===INV.cat)&&(!INV.q||(p.name+p.sku+p.brand).toLowerCase().includes(INV.q)));$('#invBody').innerHTML=invRows(l)}
function adjustPart(sku){const p=part(sku);openModal('Ajuste de inventario',`<p><b>${esc(p.name)}</b> <small>(${esc(p.unit)})</small></p><div class="mt">${stockCell(p)}</div><p class="mut mt" style="font-size:12.5px">El conteo físico corrige lo que hay <b>en mano</b>. Lo reservado para OT no cambia.</p><div class="fg mt"><div class="f"><label>Nuevo conteo físico</label><input id="aq" type="number" value="${p.stock}" min="0"></div><div class="f"><label>Motivo</label><select id="am"><option>Inventario cíclico</option><option>Merma / daño</option><option>Error de registro</option></select></div></div>`,`<button class="btn btn-o" onclick="closeModal()">Cancelar</button><button class="btn btn-b" onclick="saveAdjust('${sku}')">Guardar ajuste</button>`)}
function saveAdjust(sku){const p=part(sku),n=+$('#aq').value,d=n-p.stock;if(d){moveKardex(sku,'ajuste',d,$('#am').value);p.stock=n;audit(`Ajustó ${sku}: ${d>0?'+':''}${d} (${$('#am').value})`)}closeModal();save();toast('Ajuste registrado en kardex','check');refresh()}
function newPart(){openModal('Nuevo repuesto',`<div class="fg"><div class="f"><label>SKU</label><input id="npS"></div><div class="f"><label>Nombre</label><input id="npN"></div></div><div class="fg3"><div class="f"><label>Categoría</label><input id="npC" value="Motor"></div><div class="f"><label>Marca</label><input id="npB"></div><div class="f"><label>Ubicación</label><input id="npL" value="A-01"></div></div><div class="fg3"><div class="f"><label>Costo</label><input id="npK" type="number"></div><div class="f"><label>Precio venta</label><input id="npP" type="number"></div><div class="f"><label>Stock mínimo</label><input id="npM" type="number" value="2"></div></div><div class="f"><label>Proveedor</label><select id="npV">${S.suppliers.map(s=>`<option value="${s.id}">${esc(s.n)}</option>`).join('')}</select></div>`,`<button class="btn btn-o" onclick="closeModal()">Cancelar</button><button class="btn btn-y" onclick="savePart()">Guardar</button>`)}
function savePart(){const s=$('#npS').value.trim().toUpperCase(),n=$('#npN').value.trim();if(!s||!n||part(s)){toast('SKU y nombre válidos (el SKU no debe repetirse)','alert');return}S.parts.push(P(s,n,$('#npC').value,$('#npB').value,+$('#npK').value||0,+$('#npP').value||0,0,+$('#npM').value||0,$('#npL').value,$('#npV').value));audit('Creó repuesto '+s);closeModal();save();toast('Repuesto creado','box');refresh()}
function exportStock(){downloadCSV('stock_'+D(0),[['SKU','Repuesto','Categoría','Marca','Ubicación','Costo','Venta','Stock','Mínimo','Reservado'],...S.parts.map(p=>[p.sku,p.name,p.cat,p.brand,p.loc,p.cost,p.price,p.stock,p.min,p.res])])}
function exportKardex(){downloadCSV('kardex_'+D(0),[['Fecha','SKU','Movimiento','Cantidad','Origen','Responsable'],...S.kardex.map(k=>[k.t,k.sku,k.type,k.qty,k.ref,k.who])])}

/* compras */
function mkPO(supId,lines){const id='OC-'+String(++S.counters.oc).padStart(4,'0');S.pos.unshift({id,sup:supId,date:D(0),eta:D(sup(supId).lead),st:'enviada',lines});audit(`Generó ${id} a ${sup(supId).n}`);return id}
function poFromLow(){const by={};lowParts().forEach(p=>{if(S.pos.some(po=>po.st!=='recibida'&&po.lines.some(l=>l.sku===p.sku)))return;(by[p.sup]=by[p.sup]||[]).push({sku:p.sku,qty:suggestQty(p),cost:p.cost})});
  const ids=Object.entries(by).map(([s,l])=>mkPO(s,l));save();toast(ids.length?`${ids.length} orden(es) de compra generadas: ${ids.join(', ')}`:'Ya hay OC en camino para todo lo faltante','send');INV.tab='oc';refresh()}
function quickPO(sku,qty){const p=part(sku);if(S.pos.some(po=>po.st!=='recibida'&&po.lines.some(l=>l.sku===sku))){toast('Ya hay una OC en camino para este repuesto','alert');return}const id=mkPO(p.sup,[{sku,qty:Math.max(qty,suggestQty(p)),cost:p.cost}]);save();toast(`${id} generada a ${sup(p.sup).n}`,'send');INV.tab='oc';refresh()}
function receivePO(id){const po=S.pos.find(x=>x.id===id);po.st='recibida';po.lines.forEach(l=>{const p=part(l.sku);p.stock+=l.qty;p.cost=l.cost;moveKardex(l.sku,'entrada',l.qty,`${po.id} · ${sup(po.sup).n}`)});
  // reservar lo que estaba sin stock
  S.ots.forEach(o=>{if(o.items.some(i=>i.rs==='sin stock')){reserveItems(o);if(!o.items.some(i=>i.rs==='sin stock')&&o.blocked){o.blocked=null;logOT(o,'Llegó el repuesto: OT destrabada');o.log.push({t:nowISO(),who:'Taller',txt:'Llegó el repuesto. Retomamos el trabajo en tu auto.',pub:1});waMoment(o,'retraso','llegó el repuesto que esperábamos y ya retomamos el trabajo')}}});
  recalcRes();audit('Recibió '+id);save();toast(`${id} recibida: stock actualizado y OT destrabadas`,'check');refresh()}
function newPO(){openModal('Nueva orden de compra',`<div class="f"><label>Proveedor</label><select id="oS">${S.suppliers.map(s=>`<option value="${s.id}">${esc(s.n)}</option>`).join('')}</select></div><div class="fg"><div class="f"><label>Repuesto</label><select id="oP">${S.parts.map(p=>`<option value="${p.sku}">${esc(p.name)}</option>`).join('')}</select></div><div class="f"><label>Cantidad</label><input id="oQ" type="number" value="5" min="1"></div></div>`,`<button class="btn btn-o" onclick="closeModal()">Cancelar</button><button class="btn btn-y" onclick="saveNewPO()">Enviar OC</button>`)}
function saveNewPO(){const p=part($('#oP').value);const id=mkPO($('#oS').value,[{sku:p.sku,qty:+$('#oQ').value||1,cost:p.cost}]);closeModal();save();toast(id+' enviada','send');refresh()}
